const lost = $('Lost assets').first().json;
const { warranties } = $('Warranties expiring ≤30d').first().json;
if (!Array.isArray(lost.items) || !Number.isInteger(lost.total) || lost.total < 0 || !Array.isArray(warranties)) {
  throw new Error('Unexpected AssetNest response');
}
const expiring = warranties.filter((warranty) => warranty.derivedStatus === 'expiring_30');
const lines = [
  'AssetNest digest — ' + new Date().toISOString().slice(0, 10),
  'Lost assets: ' + lost.total,
];
for (const asset of lost.items.slice(0, 10)) lines.push(` - ${asset.assetTag}: ${asset.displayName} (${asset.status})`);
lines.push('Warranties expiring within 30 days: ' + expiring.length);
for (const warranty of expiring.slice(0, 10)) lines.push(` - ${warranty.assetTag}: ${warranty.provider} expires ${warranty.expiresOn}`);
return [{ json: { digest: lines.join('\n'), lostCount: lost.total, expiringCount: expiring.length } }];
